// Carry the filename forward alongside the binary PDF data
const filename = $('Prepare compilation ready').first().json.filename || "Resume.pdf";
const candidateName = $('Prepare compilation ready').first().json.candidateName || "Candidate";
const keywordCoverage = $('Prepare compilation ready').first().json.keywordCoverage ?? 100;

// Pass binary through untouched, just add metadata
const item = $input.first();

return [{
  json: {
    filename,
    candidateName,
    keywordCoverage
  },
  binary: {
    pdfData: item.binary.pdfData
  }
}];

const raw = $input.first().json.output || "";

// Pull candidate name from Resume extractor for filename
let candidateName = "Candidate";
try {
  const resumeOutput = $('Resume extractor').first().json.output || "";
  const nameMatch = resumeOutput.match(/"full_name"\s*:\s*"([^"]+)"/);
  if (nameMatch) candidateName = nameMatch[1];
} catch(e) {}

// Sanitize name for filename (remove special chars)
const safeFilename = candidateName.replace(/[^a-zA-Z0-9\s]/g, "").trim().replace(/\s+/g, "_");

// 1. Strip markdown fences
let latex = raw
  .replace(/^```latex\s*/i, "")
  .replace(/^```\s*/i, "")
  .replace(/```\s*$/i, "")
  .trim();

// 2. Strip anything before \documentclass
const docStart = latex.indexOf("\\documentclass");
if (docStart > 0) {
  latex = latex.slice(docStart);
}

// 3. Strip anything after \end{document}
const docEnd = latex.lastIndexOf("\\end{document}");
if (docEnd !== -1) {
  latex = latex.slice(0, docEnd + "\\end{document}".length);
}

// ---- ATS keyword coverage check & auto-fix ----------------
function escapeLatex(s) {
  return s.replace(/\\/g, "\\textbackslash{}").replace(/([&%$#_{}~^])/g, "\\$1");
}

function parseJd(raw) {
  const clean = (raw || "")
    .replace(/```json/gi, "")
    .replace(/```/g, "")
    .trim();
  const first = clean.indexOf("{");
  const last = clean.lastIndexOf("}");
  if (first === -1 || last === -1) return null;
  try { return JSON.parse(clean.slice(first, last + 1)); } catch(e) { return null; }
}

let keywordCoverage = 100;
let missingKeywords = [];
try {
  const jd = parseJd($('JD extractor').first().json.output);
  const jdKeywords = new Set();
  if (jd) {
    (jd.priority_keywords?.high || []).forEach(k => k && jdKeywords.add(String(k).trim().toLowerCase()));
    (jd.must_have_skills || []).forEach(k => k && jdKeywords.add(String(k).trim().toLowerCase()));
    (jd.skills?.technical_skills || []).forEach(k => k && jdKeywords.add(String(k).trim().toLowerCase()));
  }
  const wanted = [...jdKeywords].filter(k => k.length > 2);
  const normalize = (s) => s.replace(/\\/g, "").toLowerCase();
  const normalizedLatex = normalize(latex);
  missingKeywords = wanted.filter(k => !normalizedLatex.includes(k));

  // Auto-inject missing keywords into the Skills section
  if (missingKeywords.length > 0) {
    const skillsIdx = latex.indexOf("\\section{Skills}");
    const endIdx = skillsIdx !== -1 ? latex.indexOf("\\end{itemize}", skillsIdx) : -1;
    if (endIdx !== -1) {
      const inject = "\\item \\textbf{JD-Matched Keywords:} " +
        missingKeywords.map(escapeLatex).join(", ") + "\n";
      latex = latex.slice(0, endIdx) + inject + latex.slice(endIdx);
    }
  }

  // Recompute coverage on the FINAL latex (escapes removed)
  const stillMissing = wanted.filter(k => !normalize(latex).includes(k));
  keywordCoverage = wanted.length ? Math.round(((wanted.length - stillMissing.length) / wanted.length) * 100) : 100;
} catch(e) {
  keywordCoverage = 100;
  missingKeywords = [];
}

// 4. Build request body
const requestBody = JSON.stringify({
  compiler: "pdflatex",
  resources: [{ main: true, content: latex }]
});

return [{
  json: {
    requestBody,
    filename: safeFilename,
    candidateName,
    latexPreview: latex.slice(0, 200),
    keywordCoverage,
    missingKeywords
  }
}];

// ── Parse ATS Score (AFTER - optimized) ─────────────────────
let atsScore = 0;
let atsRecommendation = "N/A";
let atsGaps = [];
let atsKeywords = [];

try {
  const atsRaw = $('ATS Score Agent').first().json.output || "";
  const atsClean = atsRaw
    .replace(/```json/gi, "")
    .replace(/```/g, "")
    .trim();
  const firstBrace = atsClean.indexOf("{");
  const lastBrace = atsClean.lastIndexOf("}");
  const atsJson = JSON.parse(atsClean.slice(firstBrace, lastBrace + 1));
  atsScore = atsJson.score || 0;
  atsRecommendation = atsJson.recommendation || "N/A";
  atsGaps = atsJson.gaps || [];
  atsKeywords = atsJson.top_matching_keywords || [];
} catch(e) {
  atsGaps = ["Could not parse ATS analysis"];
}

// ── Parse ATS Score (BEFORE - original resume) ───────────────
let beforeScore = 0;
try {
  const bRaw = $('ATS Score Agent (Before)').first().json.output || "";
  const bClean = bRaw
    .replace(/```json/gi, "")
    .replace(/```/g, "")
    .trim();
  const bFirst = bClean.indexOf("{");
  const bLast = bClean.lastIndexOf("}");
  const bJson = JSON.parse(bClean.slice(bFirst, bLast + 1));
  beforeScore = bJson.score || 0;
} catch(e) {}

// ── JD Keyword Coverage ───────────────────────────────────────
let keywordCoverage = 100;
try {
  keywordCoverage = $('Prepare compilation ready').first().json.keywordCoverage ?? 100;
} catch(e) {}

// ── Score emoji bar ───────────────────────────────────────────
function scoreBar(score) {
  const filled = Math.round(score / 10);
  return "🟩".repeat(filled) + "⬜".repeat(10 - filled);
}

function recommendationEmoji(rec) {
  if (rec.includes("Strong")) return "🚀";
  if (rec.includes("Good")) return "✅";
  if (rec.includes("Moderate")) return "⚠️";
  return "🔴";
}

// ── Build Telegram caption ────────────────────────────────────
const candidateName = $('Compile & convert to pdf file').first().json.candidateName || "Candidate";
const filename = $('Compile & convert to pdf file').first().json.filename || "Resume.pdf";
const resumeFilename = filename.replace(/\.pdf$/i, "") + "_resume.pdf";
const coverLetterFilename = filename.replace(/\.pdf$/i, "") + "_coverletter.html";

const improvement = atsScore - beforeScore;
const delta = improvement >= 0 ? `+${improvement}` : `${improvement}`;

const gapLines = atsGaps.map((g, i) => `   ${i + 1}. ${g}`).join("\n");

const caption = `${recommendationEmoji(atsRecommendation)} *${candidateName}* — Resume Ready

📊 *Before (your resume): ${beforeScore}/100*
📊 *After (JD-optimized): ${atsScore}/100* (${delta})
${scoreBar(atsScore)} ${atsRecommendation}

🎯 *JD Keyword Coverage: ${keywordCoverage}%*

🔍 *Top Gaps to Address:*
${gapLines}

📄 File: ${resumeFilename}
🤖 ATS-optimized & JD-matched`;

// ── Clean Cover Letter HTML ───────────────────────────────────
let coverLetterHtml = "";
try {
  const clRaw = $('Cover Letter Agent').first().json.output || "";
  coverLetterHtml = clRaw
    .replace(/^```html\s*/i, "")
    .replace(/^```\s*/i, "")
    .replace(/```\s*$/i, "")
    .trim();
  const dtIdx = coverLetterHtml.indexOf("<!DOCTYPE");
  const htmlIdx = coverLetterHtml.indexOf("<html");
  const startIdx = dtIdx !== -1 ? dtIdx : (htmlIdx !== -1 ? htmlIdx : 0);
  if (startIdx > 0) coverLetterHtml = coverLetterHtml.slice(startIdx);
} catch(e) {
  coverLetterHtml = "<html><body><p>Cover letter generation failed.</p></body></html>";
}

// ── Convert HTML to binary for Telegram ───────────────────────
const htmlBytes = Buffer.from(coverLetterHtml, "utf-8");
const htmlBase64 = htmlBytes.toString("base64");

const pdfBinary = $('Compile & convert to pdf file').first().binary?.pdfData;

return [{
  json: {
    caption,
    filename,
    candidateName,
    atsScore,
    beforeScore,
    atsRecommendation,
    keywordCoverage,
    resumeFilename,
    coverLetterFilename,
    coverLetterHtml,
    htmlBase64
  },
  binary: {
    pdfData: pdfBinary,
    coverLetterFile: {
      data: htmlBase64,
      mimeType: "text/html",
      fileName: coverLetterFilename,
      fileExtension: "html"
    }
  }
}];

const MAX_ITERATIONS = 10;

let prevIteration = 0;
try {
  prevIteration = $('ATS Loop Guard').first().json.iteration || 0;
} catch (e) {}

const iteration = prevIteration + 1;

let prevResume = "";
try {
  prevResume = $('Generated resume unformatted').first().json.output || "";
} catch (e) {}

let prevScore = null;
let gaps = [];
try {
  const raw = ($('ATS Score Agent').first().json.output || "")
    .replace(/```json/gi, "")
    .replace(/```/g, "")
    .trim();
  const firstBrace = raw.indexOf("{");
  const lastBrace = raw.lastIndexOf("}");
  const parsed = JSON.parse(raw.slice(firstBrace, lastBrace + 1));
  prevScore = typeof parsed.score === "number" ? parsed.score : null;
  gaps = Array.isArray(parsed.gaps)
    ? parsed.gaps.filter((g) => typeof g === "string")
    : [];
} catch (e) {}

return [{
  json: {
    iteration,
    maxIterations: MAX_ITERATIONS,
    forceDone: iteration >= MAX_ITERATIONS,
    prevScore,
    gaps,
    atsFeedback: gaps.join("\n"),
    prevResume
  }
}];

let score = null;
let recommendation = "";
let gaps = [];
try {
  const raw = ($('ATS Score Agent').first().json.output || "")
    .replace(/```json/gi, "")
    .replace(/```/g, "")
    .trim();
  const firstBrace = raw.indexOf("{");
  const lastBrace = raw.lastIndexOf("}");
  const parsed = JSON.parse(raw.slice(firstBrace, lastBrace + 1));
  score = typeof parsed.score === "number" ? parsed.score : null;
  recommendation = parsed.recommendation || "";
  gaps = Array.isArray(parsed.gaps)
    ? parsed.gaps.filter((g) => typeof g === "string")
    : [];
} catch (e) {}

let loopInfo = { iteration: 1, forceDone: false };
try {
  loopInfo = $('ATS Loop Guard').first().json;
} catch (e) {}

const done = loopInfo.forceDone === true || score === null || score >= 95;

return [{
  json: {
    done,
    score,
    recommendation,
    gaps,
    iteration: loopInfo.iteration || 1
  }
}];
